update platform_customer_speech set status=#{status},transcript=#{transcript},error_code=#{errorCode},
    usage_json=#{usageJson},finished_time=#{finishedTime},audio_millis=#{audioMillis},input_hash=#{inputHash}
where tenant_id=#{tenantId} and session_id=#{sessionId} and id=#{id} and status='RUNNING' and deadline > #{finishedTime}
